INSERT INTO `wp_postmeta` VALUES (2822,987657,'_elementor_data','[{\"id\":\"6e6b83a\",\"elType\":\"container\",\"isInner\":false,\"settings\":{\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"6d9eba1\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"slides\",\"settings\":{\"slides\":[{\"_id\":\"slide_1\",\"heading\":\"Backing the founders building India\'s industrial backbone.\",\"description\":\"We invest our own patient capital into ambitious Indian companies solving technically hard problems across aerospace, heavy engineering, nuclear energy, and space technology.\",\"button_text\":\"Explore Our Investments \\u2197\",\"link\":{\"url\":\"\\/wordpress\\/investments\\/\"},\"background_image\":{\"url\":\"http:\\/\\/localhost\\/wordpress\\/wp-content\\/uploads\\/gdas\\/hero-builders.jpg\",\"id\":987683},\"background_color\":\"#0E1113\",\"background_overlay\":\"yes\",\"background_overlay_color\":\"rgba(14, 17, 19, 0.75)\",\"background_ken_burns\":\"yes\",\"zoom_direction\":\"in\"},{\"_id\":\"slide_2\",\"heading\":\"Advanced composites engineered for sovereign flight.\",\"description\":\"Kineco builds mission-critical composite assemblies for aerospace, defence, and high-speed rail\\u2014capabilities requiring years of expertise and precision tooling.\",\"button_text\":\"Why We Invested in Kineco \\u2192\",\"link\":{\"url\":\"\\/wordpress\\/investments\\/#kineco\"},\"background_image\":{\"url\":\"http:\\/\\/localhost\\/wordpress\\/wp-content\\/uploads\\/gdas\\/kineco.jpg\",\"id\":987684},\"background_color\":\"#0E1113\",\"background_overlay\":\"yes\",\"background_overlay_color\":\"rgba(14, 17, 19, 0.75)\",\"background_ken_burns\":\"yes\",\"zoom_direction\":\"in\"},{\"_id\":\"slide_3\",\"heading\":\"Engineering India\\u2019s low-carbon baseload power.\",\"description\":\"CORE Energy Systems provides specialised equipment manufacturing and project execution across nuclear power and national defence.\",\"button_text\":\"Why We Invested in CORE \\u2192\",\"link\":{\"url\":\"\\/wordpress\\/investments\\/#core-energy\"},\"background_image\":{\"url\":\"http:\\/\\/localhost\\/wordpress\\/wp-content\\/uploads\\/gdas\\/core-energy.jpg\",\"id\":987685},\"background_color\":\"#0E1113\",\"background_overlay\":\"yes\",\"background_overlay_color\":\"rgba(14, 17, 19, 0.75)\",\"background_ken_burns\":\"yes\",\"zoom_direction\":\"in\"},{\"_id\":\"slide_4\",\"heading\":\"Expanding India\'s flexible access to orbit.\",\"description\":\"Agnikul Cosmos is developing customizable launch vehicles powered by patented 3D-printed rocket engines, successfully flight-tested from India\'s first private launchpad.\",\"button_text\":\"Why We Invested in Agnikul \\u2192\",\"link\":{\"url\":\"\\/wordpress\\/investments\\/#agnikul\"},\"background_image\":{\"url\":\"http:\\/\\/localhost\\/wordpress\\/wp-content\\/uploads\\/gdas\\/agnikul.jpg\",\"id\":987687},\"background_color\":\"#0E1113\",\"background_overlay\":\"yes\",\"background_overlay_color\":\"rgba(14, 17, 19, 0.75)\",\"background_ken_burns\":\"yes\",\"zoom_direction\":\"in\"},{\"_id\":\"slide_5\",\"heading\":\"Securing the gases that vital industries depend on.\",\"description\":\"AirLife supplies helium and high-purity gases indispensable for semiconductor chip fabrication, medical imaging, and aerospace research.\",\"button_text\":\"Why We Invested in AirLife \\u2192\",\"link\":{\"url\":\"\\/wordpress\\/investments\\/#airlife\"},\"background_image\":{\"url\":\"http:\\/\\/localhost\\/wordpress\\/wp-content\\/uploads\\/gdas\\/airlife-gases.jpg\",\"id\":987686},\"background_color\":\"#0E1113\",\"background_overlay\":\"yes\",\"background_overlay_color\":\"rgba(14, 17, 19, 0.75)\",\"background_ken_burns\":\"yes\",\"zoom_direction\":\"in\"}],\"slides_height\":{\"unit\":\"px\",\"size\":680,\"sizes\":[]},\"slides_height_tablet\":{\"unit\":\"px\",\"size\":560,\"sizes\":[]},\"slides_height_mobile\":{\"unit\":\"px\",\"size\":480,\"sizes\":[]},\"effect\":\"fade\",\"autoplay\":\"yes\",\"autoplay_speed\":6500,\"pause_on_hover\":\"yes\",\"infinite\":\"yes\",\"navigation\":\"both\",\"content_animation\":\"fadeInUp\",\"horizontal_position\":\"left\",\"vertical_position\":\"middle\",\"text_align\":\"left\"},\"elements\":[]}]},{\"id\":\"763c2fd\",\"elType\":\"container\",\"isInner\":false,\"settings\":{\"content_width\":\"boxed\",\"boxed_width\":{\"unit\":\"px\",\"size\":1260,\"sizes\":[]},\"padding\":{\"unit\":\"px\",\"top\":\"60px\",\"right\":\"24\",\"bottom\":\"60px\",\"left\":\"24\",\"isLinked\":false},\"background_background\":\"classic\",\"background_color\":\"#EAEAE7\"},\"elements\":[{\"id\":\"6c94cb6\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"flex_direction\":\"row\",\"flex_direction_tablet\":\"column\",\"gap\":{\"unit\":\"px\",\"size\":32,\"sizes\":[]}},\"elements\":[{\"id\":\"34905c2\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":33,\"sizes\":[]}},\"elements\":[{\"id\":\"997f9ce\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"icon-box\",\"settings\":{\"selected_icon\":{\"value\":\"fas fa-vault\",\"library\":\"fa-solid\"},\"title_text\":\"Private Balance Sheet\",\"description_text\":\"We deploy our own capital. No LP fund clocks, no artificial exit pressures.\",\"title_size\":\"h4\",\"position\":\"top\",\"title_color\":\"#0E1113\",\"description_color\":\"#4A5056\"},\"elements\":[]}]},{\"id\":\"f9c30a1\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":33,\"sizes\":[]}},\"elements\":[{\"id\":\"dbc6cf4\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"icon-box\",\"settings\":{\"selected_icon\":{\"value\":\"fas fa-layer-group\",\"library\":\"fa-solid\"},\"title_text\":\"Four Anchor Platforms\",\"description_text\":\"High-conviction investments in Kineco, CORE Energy, AirLife Gases, and Agnikul.\",\"title_size\":\"h4\",\"position\":\"top\",\"title_color\":\"#0E1113\",\"description_color\":\"#4A5056\"},\"elements\":[]}]},{\"id\":\"3ef419d\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":33,\"sizes\":[]}},\"elements\":[{\"id\":\"7860321\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"icon-box\",\"settings\":{\"selected_icon\":{\"value\":\"fas fa-infinity\",\"library\":\"fa-solid\"},\"title_text\":\"10+ Year Horizon\",\"description_text\":\"Patient partnership for businesses with complex engineering and long qualification cycles.\",\"title_size\":\"h4\",\"position\":\"top\",\"title_color\":\"#0E1113\",\"description_color\":\"#4A5056\"},\"elements\":[]}]}]}]},{\"id\":\"fa0a00d\",\"elType\":\"container\",\"isInner\":false,\"settings\":{\"content_width\":\"boxed\",\"boxed_width\":{\"unit\":\"px\",\"size\":1260,\"sizes\":[]},\"padding\":{\"unit\":\"px\",\"top\":\"90px\",\"right\":\"24\",\"bottom\":\"90px\",\"left\":\"24\",\"isLinked\":false},\"background_background\":\"classic\",\"background_color\":\"#FFFFFF\"},\"elements\":[{\"id\":\"bc01176\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"flex_direction\":\"row\",\"flex_direction_tablet\":\"column\",\"gap\":{\"unit\":\"px\",\"size\":48,\"sizes\":[]},\"align_items\":\"center\"},\"elements\":[{\"id\":\"619c70c\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":55,\"sizes\":[]}},\"elements\":[{\"id\":\"6ea5629\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"heading\",\"settings\":{\"title\":\"OUR THESIS\",\"header_size\":\"h6\",\"align\":\"left\",\"title_color\":\"#B88E44\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":\"14\",\"sizes\":[]}},\"elements\":[]},{\"id\":\"b7ab5f3\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"heading\",\"settings\":{\"title\":\"India\\u2019s next generation of companies will not be built only in software.\",\"header_size\":\"h2\",\"align\":\"left\",\"typography_font_weight\":\"700\",\"title_color\":\"#0E1113\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":\"40\",\"sizes\":[]}},\"elements\":[]},{\"id\":\"420c066\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"text-editor\",\"settings\":{\"editor\":\"<p>For years, Indian venture capital was largely understood through consumer internet, fintech, and software services. That era laid vital digital foundations, but India is ready for something substantially broader.<\\/p><p>The defining businesses of the next thirty years will be forged in workshops, precision machining bays, engineering centres, and launch facilities.<\\/p><blockquote style=\'border-left: 4px solid #B88E44; padding-left: 1.5rem; margin: 1.5rem 0; font-weight: 600; color: #0E1113;\'>\\u201cThese businesses take years to build. They solve technically hard problems and require founders willing to build before the market makes it obvious.\\u201d<\\/blockquote>\",\"text_color\":\"#4A5056\"},\"elements\":[]}]},{\"id\":\"6dfef80\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":45,\"sizes\":[]}},\"elements\":[{\"id\":\"e6f5a15\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"image\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/wordpress\\/wp-content\\/uploads\\/gdas\\/india-building.jpg\",\"id\":987688,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"full\",\"border_radius\":{\"unit\":\"px\",\"top\":\"12\",\"right\":\"12\",\"bottom\":\"12\",\"left\":\"12\",\"isLinked\":true},\"box_shadow_box_shadow_type\":\"yes\",\"box_shadow_box_shadow\":{\"horizontal\":0,\"vertical\":12,\"blur\":30,\"spread\":0,\"color\":\"rgba(0,0,0,0.1)\"}},\"elements\":[]}]}]}]},{\"id\":\"27a8a01\",\"elType\":\"container\",\"isInner\":false,\"settings\":{\"content_width\":\"boxed\",\"boxed_width\":{\"unit\":\"px\",\"size\":1260,\"sizes\":[]},\"padding\":{\"unit\":\"px\",\"top\":\"95px\",\"right\":\"24\",\"bottom\":\"95px\",\"left\":\"24\",\"isLinked\":false},\"background_background\":\"classic\",\"background_color\":\"#0E1113\"},\"elements\":[{\"id\":\"b8b15da\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"heading\",\"settings\":{\"title\":\"PORTFOLIO\",\"header_size\":\"h6\",\"align\":\"center\",\"title_color\":\"#B88E44\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":\"14\",\"sizes\":[]}},\"elements\":[]},{\"id\":\"c10cc88\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"heading\",\"settings\":{\"title\":\"Companies We Have Backed\",\"header_size\":\"h2\",\"align\":\"center\",\"typography_font_weight\":\"700\",\"title_color\":\"#FFFFFF\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":\"44\",\"sizes\":[]}},\"elements\":[]},{\"id\":\"937dbea\",\"elType\":\"widget\",\"isInner\":false,\"widgetType\":\"text-editor\",\"settings\":{\"editor\":\"<p style=\\\"text-align: center; max-width: 680px; margin: 0 auto 3rem;\\\">Every investment begins with conviction in a company, its founders, and what they are setting out to build.<\\/p>\",\"text_color\":\"#CBD5E1\"},\"elements\":[]},{\"id\":\"a3371ce\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"flex_direction\":\"row\",\"flex_direction_tablet\":\"column\",\"gap\":{\"unit\":\"px\",\"size\":32,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"32\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"75b153c\",\"elType\":\"container\",\"isInner\":true,\"settings\":{\"width\":{\"unit\":\"%\",\"size\":48,\"sizes\":[]},\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":1,\"right\":1,\"bottom\":1,\"left\":1,\"isLinked\":true},\"border_color\":\"rgba(255, 255, 255, 0.12)\",\"border_radius\":{\"unit\"